<script>/*MARKED_JS*/</script>
<script>
function escapeHtml(s) {
  return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;")
    .replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

// The model's output is untrusted: no raw HTML, no images, http(s) links only.
marked.use({
  renderer: {
    html: function (h) { return escapeHtml(h); },
    image: function (href, title, text) { return escapeHtml(text || ""); },
    link: function (href, title, text) {
      if (!/^https?:/i.test(href || "")) { return text; }
      return '<a href="' + escapeHtml(href) + '">' + text + '</a>';
    }
  }
});
marked.setOptions({ gfm: true, breaks: false });

var chat = document.getElementById("chat");

function scrollToBottom() {
  window.scrollTo(0, document.body.scrollHeight);
}

function decorate(bubble) {
  var pres = bubble.querySelectorAll("pre");
  for (var i = 0; i < pres.length; i++) {
    (function (pre) {
      var wrap = document.createElement("div");
      wrap.className = "codewrap";
      pre.parentNode.insertBefore(wrap, pre);
      wrap.appendChild(pre);
      var btn = document.createElement("button");
      btn.className = "copy";
      btn.textContent = "Copy";
      btn.onclick = function () {
        var ta = document.createElement("textarea");
        ta.value = pre.innerText;
        ta.style.position = "fixed";
        ta.style.opacity = "0";
        document.body.appendChild(ta);
        ta.select();
        try { document.execCommand("copy"); } catch (e) {}
        document.body.removeChild(ta);
        btn.textContent = "Copied";
        setTimeout(function () { btn.textContent = "Copy"; }, 1200);
      };
      wrap.appendChild(btn);
    })(pres[i]);
  }
  var tables = bubble.querySelectorAll("table");
  for (var j = 0; j < tables.length; j++) {
    var t = tables[j];
    var tw = document.createElement("div");
    tw.className = "tablewrap";
    t.parentNode.insertBefore(tw, t);
    tw.appendChild(t);
  }
}

function addMessage(role, text, voice) {
  hideTyping();
  var row = document.createElement("div");
  row.className = "row " + role + (voice ? " voice" : "");
  var bubble = document.createElement("div");
  bubble.className = "bubble";
  if (role === "error") {
    var parts = String(text).split("\\n");
    var title = document.createElement("div");
    title.className = "title";
    title.textContent = parts.shift();
    bubble.appendChild(title);
    var rest = parts.join("\\n").trim();
    if (rest) {
      var det = document.createElement("details");
      var sum = document.createElement("summary");
      sum.textContent = "Details";
      var pre = document.createElement("pre");
      pre.textContent = rest;
      det.appendChild(sum);
      det.appendChild(pre);
      bubble.appendChild(det);
    }
  } else if (role === "assistant") {
    var html = marked.parse(String(text));
    bubble.innerHTML = html;
    if (/<table|<pre/.test(html)) { bubble.className += " wide"; }
    decorate(bubble);
  } else {
    bubble.textContent = text;
  }
  row.appendChild(bubble);
  chat.appendChild(row);
  scrollToBottom();
}

function showTyping() {
  if (document.getElementById("typing")) { return; }
  var row = document.createElement("div");
  row.className = "row assistant";
  row.id = "typing";
  row.innerHTML = '<div class="bubble"><span class="dots"><span></span><span></span><span></span></span></div>';
  chat.appendChild(row);
  scrollToBottom();
}

function hideTyping() {
  var el = document.getElementById("typing");
  if (el) { el.parentNode.removeChild(el); }
}
function setTheme(name) {
  document.documentElement.className = (name === "dark") ? "dark" : "";
}

function clearChat() {
  chat.innerHTML = "";
}
</script>
</body>
</html>

